#!/usr/bin/env python3
"""Regenerate the b72e2687 register CSVs with correct CSV quoting.

The first hand-written versions left commas inside fields unquoted, which shifted
columns on parse. This rewrites every register from the intended row data using
Python's csv writer so quoting is always correct.
"""
from __future__ import annotations

import csv
import os

REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DATA = os.path.join(REPO, "data", "nfl_b72e2687")


def write(name, header, rows):
    with open(os.path.join(DATA, name), "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(header)
        w.writerows(rows)
    print(f"wrote {name}: {len(rows)} rows")


